mapper.select:
select id, order_no, applicant_name, approval_status, created_at
from requisition_order


        and order_no like concat('%', #{orderNo}, '%')


        and applicant_name like concat('%',#{applicantName},'%')


        and applicant_department_name like concat('%',#{departmentName},'%')



        and approver_name like concat('%',#{approverName},'%')


        and approval_status = #{approvalStatus}


        AND created_at >= #{startDate}


        AND created_at <= #{endDate}
